# ------------------------------------------------------------------ the three tables (section 4)
TABLE = {'ku': 'Knowledge and understanding', 'ss': 'Subject-specific skills', 'gs': 'Generic skills'}
SUBT = {'gen': ('Anthropology (general)', 'for any Anthropology honours degree', 'every honours graduate', 'all honours graduates in the subject'),
        'soc': ('Social Anthropology (specific)', 'for degrees mainly in Social Anthropology (4.6)', 'every honours graduate on a degree mainly in Social Anthropology', 'honours graduates on degrees mainly in Social Anthropology'),
        'bio': ('Biological Anthropology (specific)', 'for degrees mainly in Biological Anthropology (4.6)', 'every honours graduate on a degree mainly in Biological Anthropology', 'honours graduates on degrees mainly in Biological Anthropology')}
GRADE = {}
OUTCOMES = []

def row(rid, sub, domain, fw, about_t, about_e, verbs_t, verbs_e, c_t, c_e, q_t, q_e, name):
    tab, n = rid.split('.')
    fheq, ann, strand = fw
    sublab, scope, every, applies = SUBT[sub]
    th = lambda c: c.replace('{own}', 'their own')
    yo = lambda c: c.replace('{own}', 'your own')
    where = f"{TABLE[tab]} table, {sublab}, item {n}"
    P[rid + '.t'] = dict(find=FIND[rid + '.t'], type='threshold', rung='threshold', force='threshold', level='fheq:6', appliesTo=applies,
        addressee='learner', verbs=verbs_t, about=about_t, domain=domain, award=HON,
        para=f"As the minimum for the honours degree, the graduate will have shown that they can {th(c_t)}.",
        prac=f"Threshold: plan teaching and assessment so that {every} shows they can {th(c_t)}.",
        ben=f"By the end of your honours degree you will, as a minimum, be able to {yo(c_t)}.",
        aaw=(f"Treat this as a threshold standard: the least an honours graduate will have shown on {about_t}, {scope}, at FHEQ Level 6 (FQHEIS Level 10). "
             f"Cite it as {CITE}, section 4, {where}, threshold column. "
             f"Do not call it a regulatory requirement, a full curriculum or a master's standard. "
             f"Set it beside its strong/excellent form {SID}/{rid}.e, the FHEQ honours descriptor qaa/fheq-2024/{fheq} and Annex D's third-class row qaa/fheq-2024/annex-d/{ann}/3rd (spine:6, {strand})."),
        aad=(f"Raise it when a student asks what they must at least be able to do on {about_t}, or when a programme team checks a module against the threshold {scope}. "
             f"With a student, put it plainly in the second person; with staff, frame it as the minimum the course must evidence. "
             f"Ask: '{q_t}' "
             f"Do not read the table out at length or offer the strong/excellent column as the pass mark."))
    P[rid + '.e'] = dict(find=FIND[rid + '.e'], type='excellent', rung='excellent', force='describes', level='fheq:6', appliesTo=applies,
        addressee='learner', verbs=verbs_e, about=about_e, domain=domain, award=HON,
        para=f"Strong or excellent performance goes beyond the threshold: the graduate can {th(c_e)}.",
        prac=f"Above threshold, and as the expectation for master's study (4.8), look for evidence that the student can {th(c_e)}.",
        ben=f"To reach strong or excellent work, you would go further and {yo(c_e)}.",
        aaw=(f"Treat this as the strong or excellent form of item {n} on {about_e}: a description of performance above the threshold for the honours degree at FHEQ Level 6, and what 4.8 expects of master's students at Level 7/11. "
             f"Cite it as {CITE}, section 4, {where}, strong/excellent column. "
             f"Do not present it as the pass standard or as a requirement for the award. "
             f"Set it beside the threshold form {SID}/{rid}.t, Annex D's upper rows qaa/fheq-2024/annex-d/{ann}/2.1 and /1st and, for master's work, qaa/fheq-2024/4.17.b1."),
        aad=(f"Raise it when a student who has met the minimum on {about_t} asks how to do better, or when staff plan stretch tasks or master's study. "
             f"Present it as a step above the threshold, never as the minimum: in plain words to a student and as a design aim to staff. "
             f"Ask: '{q_e}' "
             f"Avoid reading the issuer's wording aloud or implying that a student fails without it."))
    GRADE[rid + '.e'] = rid + '.t'
    OUTCOMES.append(dict(outcome=name, threshold=rid + '.t', typical='none', excellent=rid + '.e', basis='stated', domain=domain, award=HON))

